```go
// Save persists settings to .entire/settings.json. Caller is responsible
// for ensuring the directory exists; Save creates it if missing.
func Save(ctx context.Context, s *EntireSettings) error {
    path, err := paths.AbsPath(ctx, EntireSettingsFile)
    if err != nil { return fmt.Errorf("resolve settings path: %w", err) }
    if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
        return fmt.Errorf("create settings dir: %w", err)
    }
    data, err := json.MarshalIndent(s, "", "  ")
    if err != nil { return fmt.Errorf("marshal settings: %w", err) }
    tmp := path + ".tmp"
    if err := os.WriteFile(tmp, data, 0o600); err != nil {
        return fmt.Errorf("write settings: %w", err)
    }
    if err := os.Rename(tmp, path); err != nil {
        return fmt.Errorf("rename settings: %w", err)
    }
    return nil
}
```

