// BuildPickRolesFields constructs one huh.Select per agent. Exported
// for tests; the form-runner closure realPickRoles wraps it.
func BuildPickRolesFields(agents []string, current map[string]settings.Role) []huh.Field {
    fields := make([]huh.Field, 0, len(agents))
    opts := []huh.Option[settings.Role]{
        huh.NewOption("Reviewer", settings.RoleReviewer).
            Description("Runs on `entire review`. Multiple agents allowed."),
        huh.NewOption("Fixer", settings.RoleFixer).
            Description("Runs on `entire review fix`. Exactly one across the config."),
        huh.NewOption("Both", settings.RoleBoth).
            Description("Reviews AND fixes. Counts as the Fixer."),
        huh.NewOption("Skip", settings.RoleSkip).
            Description("Configured but not used by review."),
    }
    for _, a := range agents {
        a := a // capture
        sel := huh.NewSelect[settings.Role]().
            Title(displayLabelFor(a)).
            Options(opts...).
            Value(getMapPtr(current, a)) // helper that returns *settings.Role for `current[a]`
        fields = append(fields, sel)
    }
    return fields
}

// realPickRoles is the production form runner — used when SetupForms.PickRoles is nil.
func realPickRoles(ctx context.Context, agents []string, current map[string]settings.Role) (map[string]settings.Role, error) {
    fields := BuildPickRolesFields(agents, current)
    form := newAccessibleForm(huh.NewGroup(fields...))
    if err := form.RunWithContext(ctx); err != nil {
        return nil, fmt.Errorf("roles picker: %w", err)
    }
    return current, nil
}
```

`displayLabelFor(agentName)` returns the human-readable agent label (e.g. `"Claude Code"` for `"claude-code"`); use `agent.Get(types.AgentName(agentName)).Type()` to resolve, falling back to the raw name if `agent.Get` errors.

`getMapPtr(m, k)` is a small helper that materializes a default in `m[k]` (Reviewer if unset) and returns a pointer to the map's underlying value — Go map values aren't addressable, so this requires a small trick: keep an intermediate slice of `settings.Role` pointers and reconcile back to the map after `form.Run`.

Simpler: avoid the addressability issue by closing over a `map[string]*settings.Role` for the form, then copy back to the `map[string]settings.Role` on success:

```go
ptrs := make(map[string]*settings.Role, len(current))
for _, a := range agents {
    v := current[a]
    if v == "" { v = settings.RoleReviewer }
    ptrs[a] = &v
}
// Build fields binding *settings.Role values from ptrs.
