func TestSetupSubcommand_Registered(t *testing.T) {
	t.Parallel()
	root := review.NewCommand(testDepsForSetupSubcommand(t))
	setup, _, err := root.Find([]string{"setup"})
	if err != nil {
		t.Fatalf("setup subcommand not found: %v", err)
